function TokenFooter({ usage }: { usage: TokenUsage }) {
  const items = [
    { label: "In",          value: usage.input_tokens },
    { label: "Out",         value: usage.output_tokens },
    { label: "Cache write", value: usage.cache_creation_input_tokens },
