 362→// ── Strip N→ line number prefix (Read tool results) ───────────
 363→function stripLineNumbers(text: string): string {
 364→  const lines = text.split("\n");
 365→  const firstNonEmpty = lines.find((l) => l.trim() !== "");
 366→  if (firstNonEmpty && /^\d+→/.test(firstNonEmpty)) {
 367→    return lines.map((l) => l.replace(/^\d+→/, "")).join("\n");
 368→  }
 369→  return text;
 370→}
