 774→// ── Serena MCP result rendering ───────────────────────────────
 775→
 776→type SerenaResult =
 777→  | { type: "text"; text: string }
 778→  | { type: "structured"; data: Record<string, unknown> };
 779→
 780→function parseSerenaResult(content: string): SerenaResult | null {
 781→  try {
 782→    const outer = JSON.parse(content);
 783→    if (typeof outer !== "object" || outer === null || !("result" in outer)) return null;
 784→    const resultVal = (outer as Record<string, unknown>).result;
 785→    if (typeof resultVal !== "string") return null;
 786→    try {
 787→      const inner = JSON.parse(resultVal);
 788→      if (typeof inner === "object" && inner !== null)
 789→        return { type: "structured", data: inner as Record<string, unknown> };
 790→    } catch {
 791→      // resultVal is plain text, not JSON
 792→    }
 793→    return { type: "text", text: resultVal };
 794→  } catch {
 795→    return null;
 796→  }
 797→}
 798→
 799→function PathList({ items }: { items: string[] }) {
 800→  return (
 801→    <div style={{ display: "flex", flexDirection: "column", gap: "2px" }}>
 802→      {items.map((item, i) => (
 803→        <div
 804→          key={i}
 805→          style={{
 806→            fontFamily: "var(--font-mono)",
 807→            fontSize: "12px",
 808→            color: "var(--text-2)",
 809→            padding: "2px 0",
 810→            borderBottom: "1px solid var(--border-1)",
 811→            wordBreak: "break-all",
 812→          }}
 813→        >
 814→          {item}
 815→        </div>
 816→      ))}
 817→    </div>
 818→  );
 819→}
 820→
 821→function SerenaResultDisplay({ content }: { content: string }) {
 822→  const parsed = parseSerenaResult(content);
 823→  if (!parsed) return <CodeRender content={content} />;
 824→  if (parsed.type === "text") return <MarkdownContent text={parsed.text} />;
 825→
 826→  const { data } = parsed;
 827→  const dirs  = Array.isArray(data.dirs)  ? (data.dirs  as string[]) : [];
 828→  const files = Array.isArray(data.files) ? (data.files as string[]) : [];
 829→  const rest  = Object.entries(data).filter(([k]) => k !== "dirs" && k !== "files");
 830→
 831→  return (
 832→    <div>
 833→      {dirs.length > 0 && (
 834→        <ContentSection label={`Dirs · ${dirs.length}`} color="var(--cyan)">
 835→          <PathList items={dirs} />
 836→        </ContentSection>
 837→      )}
 838→      {files.length > 0 && (
 839→        <ContentSection label={`Files · ${files.length}`} color="var(--green)">
 840→          <PathList items={files} />
 841→        </ContentSection>
 842→      )}
 843→      {rest.map(([k, v]) => (
 844→        <ContentSection key={k} label={k}>
 845→          <CodeRender content={typeof v === "string" ? v : JSON.stringify(v, null, 2)} />
 846→        </ContentSection>
 847→      ))}
 848→    </div>
 849→  );
 850→}
