 952→  const replaceAll = input.replace_all === true;
 953→
 954→  const removedLines = oldString?.split("\n") ?? [];
 955→  const addedLines   = newString?.split("\n")  ?? [];
 956→
 957→  const fileName = filePath?.split("/").pop() ?? filePath ?? "edit";
 958→
 959→  return (
 960→    <ContentSection label="Edit" color="var(--text-3)">
 961→      <div style={{
 962→        borderRadius: "var(--radius-md)", overflow: "hidden",
