 964→        fontFamily: "var(--font-mono)", fontSize: "13px",
 965→      }}>
 966→
 967→        {/* ── Header bar ── */}
 968→        <div style={{
 969→          display: "flex", alignItems: "center", justifyContent: "space-between",
