 971→          background: "var(--bg-2)",
 972→          borderBottom: "1px solid var(--border-1)",
 973→        }}>
 974→          <span
 975→            title={filePath ?? undefined}
 976→            style={{
 977→              color: "var(--text-2)", fontSize: "12px",
 978→              overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
 979→              maxWidth: "65%",
 980→            }}
 981→          >
 982→            {fileName}
 983→          </span>
 984→
 985→          <div style={{ display: "flex", alignItems: "center", gap: "12px", flexShrink: 0 }}>
 986→            {removedLines.length > 0 && (
 987→              <span style={{ color: "var(--red)", opacity: 0.75, fontSize: "12px" }}>
 988→                −{removedLines.length}
 989→              </span>
 990→            )}
 991→            {addedLines.length > 0 && (
 992→              <span style={{ color: "var(--green)", opacity: 0.75, fontSize: "12px" }}>
 993→                +{addedLines.length}
 994→              </span>
 995→            )}
 996→            {replaceAll && (
 997→              <span style={{
 998→                padding: "1px 7px", borderRadius: "var(--radius-sm)",
 999→                border: "1px solid rgba(255,181,71,0.25)",
1000→                fontSize: "10px", letterSpacing: "0.06em", textTransform: "uppercase",
1001→                color: "var(--amber)", opacity: 0.85,
1002→              }}>
1003→                all
1004→              </span>
1005→            )}
1006→          </div>
1007→        </div>
1008→
1009→        {/* ── Diff lines ── */}
1010→        <div style={{ maxHeight: "480px", overflowY: "auto" }}>
1011→          {removedLines.map((line, i) => (
1012→            <div key={`r${i}`} style={{
1013→              display: "flex", alignItems: "flex-start",
1014→              background: "rgba(255,69,69,0.055)",
1015→              borderLeft: "2px solid rgba(255,69,69,0.38)",
1016→            }}>
1017→              <span style={{
1018→                width: "34px", flexShrink: 0, textAlign: "center",
1019→                padding: "3px 0", lineHeight: 1.6,
1020→                color: "rgba(255,100,100,0.55)", userSelect: "none", fontSize: "12px",
1021→              }}>−</span>
1022→              <span style={{
1023→                flex: 1, padding: "3px 14px 3px 0",
1024→                color: "var(--text-3)", lineHeight: 1.6,
1025→                whiteSpace: "pre-wrap", wordBreak: "break-all",
1026→              }}>
1027→                {line || "\u00a0"}
1028→              </span>
1029→            </div>
1030→          ))}
1031→
1032→          {removedLines.length > 0 && addedLines.length > 0 && (
1033→            <div style={{ height: "1px", background: "var(--border-1)" }} />
1034→          )}
1035→
1036→          {addedLines.map((line, i) => (
1037→            <div key={`a${i}`} style={{
